import {
  Group,
  Mesh,
  BoxGeometry,
  PlaneGeometry,
  Color,
  Vector3,
  FrontSide,
} from 'three/webgpu';
import {
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
  mix,
  uv,
  rotateUV,
  add,
  mul,
  clamp,
  lessThan,
  cond,
  vec2,
  nodeObject,
} from 'three/tsl';
import { gsap } from 'gsap';
import primitives from '@/primitives';
import { createTextMesh } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Object} textContent
 * @property {Object} visual
 * @property {Array<Object>} cinematicPrimitives
 * @property {Object} placement
 */

/**
 * @typedef {Object} NodeContext
 * @property {Object} primitives
 * @property {Object} fontAtlas
 * @property {Object} textureLoader
 * @property {Object} glbLoader
 */

/**
 * Helper to build a gradient node rotated 135° (3π/4 rad)
 */
function buildGradientNode() {
  const uvRot = rotateUV(uv(), Math.PI * 0.75);
  const t = clamp(uvRot.x, 0, 1);
  const c0 = new Color('#101017');
  const c1 = new Color('#1a1a22');
  return mix(c0, c1, t);
}

/**
 * Create a single cell (slab + tick + texts)
 */
function createCell({
  width,
  height,
  depth = 0.06,
  padding = 0.5,
  value,
  valueStyle,
  label,
  labelStyle,
  isDominant,
}) {
  const cellGroup = new Group();

  // Slab geometry
  const slabGeom = new BoxGeometry(width, height, depth);
  // Gradient material
  const slabMat = new MeshStandardNodeMaterial({
    colorNode: buildGradientNode(),
    metalness: 0.45,
    roughness: 0.5,
    clearcoat: 0.2,
    side: FrontSide,
  });
  const slab = new Mesh(slabGeom, slabMat);
  slab.position.set(0, 0, depth / 2);
  slab.castShadow = true;
  slab.receiveShadow = true;
  cellGroup.add(slab);

  // Tick bar
  const tickWidth = 0.4;
  const tickHeight = 0.05;
  const tickDepth = 0.001;
  const tickGeom = new BoxGeometry(tickWidth, tickHeight, tickDepth);
  const tickMat = new MeshBasicNodeMaterial({
    color: new Color('#ff2a38'),
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 1.3,
    transparent: true,
    opacity: 1,
    side: FrontSide,
  });
  const tick = new Mesh(tickGeom, tickMat);
  const tickX = -width / 2 + padding + tickWidth / 2;
  const tickY = height / 2 - padding - tickHeight / 2;
  tick.position.set(tickX, tickY, depth + tickDepth);
  cellGroup.add(tick);

  // Value text
  const valueMesh = createTextMesh(value, {
    ...valueStyle,
    color: '#e8ecf2',
    atlas: 0,
  });
  // Position value near top inside padding
  const valueY = height / 2 - padding - valueMesh.userData.height / 2;
  valueMesh.position.set(0, valueY, depth + tickDepth + 0.001);
  cellGroup.add(valueMesh);

  // Label text
  const labelMesh = createTextMesh(label, {
    ...labelStyle,
    color: '#e8ecf2',
    atlas: 0,
  });
  const labelY = valueY - valueMesh.userData.height / 2 - 0.1 - labelMesh.userData.height / 2;
  labelMesh.position.set(0, labelY, depth + tickDepth + 0.001);
  cellGroup.add(labelMesh);

  // Interaction handlers
  const timelines = {};

  function pressDown() {
    timelines.press = gsap.to(cellGroup.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
    });
  }

  function release() {
    timelines.release = gsap.to(cellGroup.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.9,
      ease: 'cubic-bezier(0.165,0.84,0.44,1)',
      onStart() {
        gsap.to(cellGroup.scale, {
          x: 1.04,
          y: 1.04,
          z: 1.04,
          duration: 0.09,
          ease: 'power4.out',
          yoyo: true,
          repeat: 1,
        });
      },
    });
  }

  cellGroup.userData.handlers = {
    pointerdown: pressDown,
    pointerup: release,
    pointerout: release,
  };

  // Cleanup for this cell
  cellGroup.userData.cleanup = () => {
    slabGeom.dispose();
    slabMat.dispose();
    tickGeom.dispose();
    tickMat.dispose();
    if (valueMesh.userData?.cleanup) valueMesh.userData.cleanup();
    if (labelMesh.userData?.cleanup) labelMesh.userData.cleanup();
    Object.values(timelines).forEach((t) => t?.kill());
  };

  return cellGroup;
}

/**
 * Main node creator
 */
export default function createNode(config, ctx) {
  const root = new Group();
  root.position.set(
    config.placement?.position?.[0] ?? 0,
    config.placement?.position?.[1] ?? 0,
    config.placement?.position?.[2] ?? 0
  );
  root.rotation.set(
    config.placement?.rotation?.[0] ?? 0,
    config.placement?.rotation?.[1] ?? 0,
    config.placement?.rotation?.[2] ?? 0
  );
  root.scale.set(
    config.placement?.scale?.[0] ?? 1,
    config.placement?.scale?.[1] ?? 1,
    config.placement?.scale?.[2] ?? 1
  );

  // Header caption
  const headerMesh = createTextMesh(
    config.textContent['ATELIER METRICS / Q2 2026'],
    {
      family: 'JetBrains Mono',
      fontSize: 18,
      fontWeight: 700,
      color: '#ff2a38',
      atlas: 0,
    }
  );
  headerMesh.position.set(-2.75, 0.5 + 0.5, 0);
  root.add(headerMesh);

  // Grid dimensions
  const gutter = 0.25;
  const dominantWidth = 3.25;
  const dominantHeight = 3.5;
  const secondaryWidth = 2.0;
  const secondaryHeight = 1.625;

  // Dominant cell
  const dominantCell = createCell({
    width: dominantWidth,
    height: dominantHeight,
    value: config.textContent['0.002 mm'],
    valueStyle: {
      family: 'Lora',
      fontSize: 124,
      fontWeight: 600,
      letterSpacing: -0.01,
      lineHeight: 1,
    },
    label: config.textContent['Case tolerance, CNC pass'],
    labelStyle: {
      family: 'JetBrains Mono',
      fontSize: 18,
      fontWeight: 400,
      letterSpacing: 0.08,
      lineHeight: 1.4,
    },
    isDominant: true,
  });
  dominantCell.position.set(- (dominantWidth + gutter) / 2, 0, 0);
  root.add(dominantCell);

  // Secondary cell top
  const secondaryTop = createCell({
    width: secondaryWidth,
    height: secondaryHeight,
    value: config.textContent['38 h'],
    valueStyle: {
      family: 'Lora',
      fontSize: 68,
      fontWeight: 600,
      letterSpacing: -0.005,
      lineHeight: 1.05,
    },
    label: config.textContent['Power reserve, NA-01'],
    labelStyle: {
      family: 'JetBrains Mono',
      fontSize: 18,
      fontWeight: 400,
      letterSpacing: 0.08,
      lineHeight: 1.4,
    },
    isDominant: false,
  });
  secondaryTop.position.set(
    (secondaryWidth + gutter) / 2,
    (dominantHeight / 2 - secondaryHeight / 2),
    0
  );
  root.add(secondaryTop);

  // Secondary cell bottom
  const secondaryBottom = createCell({
    width: secondaryWidth,
    height: secondaryHeight,
    value: config.textContent['214'],
    valueStyle: {
      family: 'Lora',
      fontSize: 68,
      fontWeight: 600,
      letterSpacing: -0.005,
      lineHeight: 1.05,
    },
    label: config.textContent['Components per calibre'],
    labelStyle: {
      family: 'JetBrains Mono',
      fontSize: 18,
      fontWeight: 400,
      letterSpacing: 0.08,
      lineHeight: 1.4,
    },
    isDominant: false,
  });
  secondaryBottom.position.set(
    (secondaryWidth + gutter) / 2,
    -(dominantHeight / 2 - secondaryHeight / 2),
    0
  );
  root.add(secondaryBottom);

  // Entrance animation (stagger fade-up)
  const cells = [dominantCell, secondaryTop, secondaryBottom];
  cells.forEach((cell, i) => {
    cell.position.y += 0.2;
    cell.traverse((obj) => {
      if (obj.material) {
        obj.material.transparent = true;
        obj.material.opacity = 0;
      }
    });
    gsap.to(
      { y: cell.position.y - 0.2, opacity: 0 },
      {
        y: cell.position.y,
        opacity: 1,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        delay: i * 0.08,
        onUpdate: function () {
          const progress = this.progress();
          cell.position.y = this.targets()[0].y;
          cell.traverse((obj) => {
            if (obj.material) obj.material.opacity = this.targets()[0].opacity;
          });
        },
      }
    );
  });

  // Apply cinematic primitives if any
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((primitive) => {
      const fn = ctx.primitives[primitive.name];
      if (typeof fn === 'function') {
        fn(root, primitive.params);
      }
    });
  }

  // Cleanup handling
  root.userData.cleanup = () => {
    // Dispose header mesh
    if (headerMesh.geometry) headerMesh.geometry.dispose();
    if (headerMesh.material) headerMesh.material.dispose();
    // Dispose cells
    cells.forEach((c) => {
      if (c.userData?.cleanup) c.userData.cleanup();
    });
    // Kill any global GSAP timelines (none stored globally here)
  };

  // Forward handlers up to root for external use
  root.userData.handlers = {};

  return root;
}
